#' Age Pyramid
#'
#' Generates an age pyramid from an age variable and a gender variable.
#' 
#'
#' @examples
#' \donttest{
#' # `female` and `male` are Level options: jamovi forbids a default on
#' # them, so they are REQUIRED arguments of this function. Pass NULL to
#' # have the levels read from their names.
#' agepyramid(
#'     data = histopathology,
#'     age = "Age",
#'     gender = "Sex",
#'     female = "Female",
#'     male = "Male",
#'     age_groups = "who"
#' )
#'}
#' @param data The data as a data frame.
#' @param age a string naming the variable from \code{data} that contains the
#'   continuous values used for the report
#' @param gender a string naming the variable from \code{data} that contains
#'   the categorical values used for the report
#' @param female a string naming the level of \code{gender} that identifies
#'   female subjects. This argument has no default (jamovi does not allow one on
#'   a level option), so a call from R must always supply it; pass NULL to let
#'   the analysis read the level names itself, which it reports in a note above
#'   the results.
#' @param male a string naming the level of \code{gender} that identifies male
#'   subjects. This argument has no default (jamovi does not allow one on a
#'   level option), so a call from R must always supply it; pass NULL to let the
#'   analysis read the level names itself, which it reports in a note above the
#'   results.
#' @param age_groups Predefined age group categories. Choose 'custom' to use
#'   bin_width, or select a preset. 'who' gives the WHO/UN standard five-year
#'   groups (0-4, 5-9, ... 85+) used by the WHO World Standard Population and UN
#'   population pyramids; 'who_infant' is the WHO abridged life-table grouping,
#'   which reports infants (<1) separately from children aged 1-4. All bands are
#'   left-closed, so an age on a boundary starts the band named for it.
#' @param age_interval Which end of an age band is closed. 'left' gives
#'   [lower, upper) bands, the WHO/UN and demographic convention: a person aged
#'   exactly 65 starts the 65-69 band, and equal-width bands hold equal numbers
#'   of single years. 'right' gives (lower, upper] bands, where age 65 closes
#'   the band below it; this reproduces the behaviour of releases before 1.0.52
#'   and makes the lowest band one year wider than the others, which inflates
#'   the youngest bar of the pyramid. Applies to the custom age grouping only:
#'   the named presets are defined by their sources as left-closed bands, so a
#'   right-closed setting is ignored for them and a note says so.
#' @param bin_width The width of the age bins in years. Adjust this to change
#'   the granularity of the age groups. Ignored while \code{custom_breaks} is
#'   filled in. A width that would produce more than 200 age bands is refused
#'   with an explanatory note, and more than 25 bands raises a warning about how
#'   thin the bars become.
#' @param custom_breaks Comma-separated age break points (e.g.,
#'   "0,18,25,50,65,100"). Only used when age_groups is set to 'custom'. When
#'   filled in these override bin_width; leave empty to use bin_width. Entries
#'   that are not numbers are reported in a note and left out, and the top band
#'   is always open-ended.
#' @param pct_base Denominator of the percentage columns and of the percent
#'   axis of the plots. 'within_gender' divides each band by the number of that
#'   gender, so the Female and Male columns each sum to 100 and the two sides
#'   compare the shape of the two age distributions. 'total' divides every band
#'   by the number of analysed observations, so both columns together sum to 100
#'   and the sides also reflect how many of each gender there are; the Total row
#'   then shows each gender's share.
#' @param plot_values Whether the bars of the pyramid show counts or the
#'   percentages defined by pct_base. Percentages make the two sides comparable
#'   when the genders are unequal in number. Applies to both the main and the
#'   ggcharts pyramid.
#' @param plot_title The title displayed on the age pyramid plot.
#' @param color_palette Color palette for gender visualization. Choose
#'   'custom' to specify your own colors.
#' @param female_color Custom color for female bars (hex code). Only used when
#'   color_palette is 'custom'.
#' @param male_color Custom color for male bars (hex code). Only used when
#'   color_palette is 'custom'.
#' @param originaltheme Whether to apply the original custom theme
#'   (theme_minimal with custom tweaks) instead of jamovi's default theme.
#' @param enableGGCharts Enable the ggcharts pyramid_chart() visualization as
#'   a second plot. This provides an alternative visualization style using the
#'   ggcharts package.
#' @param ggcharts_sort Sort bars by population count. Options: 'no' (default
#'   order), 'ascending' (smallest to largest), 'descending' (largest to
#'   smallest).
#' @param ggcharts_colors Color scheme for ggcharts pyramid. 'default' uses
#'   ggcharts defaults, or select from preset palettes or custom colors.
#' @param ggcharts_color1 Custom color for first group (hex code). Used when
#'   ggcharts_colors is 'custom'.
#' @param ggcharts_color2 Custom color for second group (hex code). Used when
#'   ggcharts_colors is 'custom'.
#' @param ggcharts_title Title for the ggcharts pyramid plot.
#' @param ggcharts_xlab X-axis label for ggcharts pyramid.
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$notices} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$welcome} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$dataInfo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$pyramidTable} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$plot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plotGGCharts} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$pyramidTable$asDF}
#'
#' \code{as.data.frame(results$pyramidTable)}
#'
#' @export
agepyramid <- function(
    data,
    age = NULL,
    gender = NULL,
    female,
    male,
    age_groups = "custom",
    age_interval = "left",
    bin_width = 5,
    custom_breaks = "",
    pct_base = "within_gender",
    plot_values = "count",
    plot_title = "Age Pyramid",
    color_palette = "standard",
    female_color = "#E91E63",
    male_color = "#2196F3",
    originaltheme = FALSE,
    enableGGCharts = FALSE,
    ggcharts_sort = "no",
    ggcharts_colors = "default",
    ggcharts_color1 = "#1F77B4",
    ggcharts_color2 = "#FF7F0E",
    ggcharts_title = "Age Pyramid (ggcharts)",
    ggcharts_xlab = "Population") {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("agepyramid requires jmvcore to be installed (restart may be required)")

    if ( ! missing(age)) age <- jmvcore::resolveQuo(jmvcore::enquo(age))
    if ( ! missing(gender)) gender <- jmvcore::resolveQuo(jmvcore::enquo(gender))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(age), age, NULL),
            `if`( ! missing(gender), gender, NULL))

    for (v in gender) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- agepyramidOptions$new(
        age = age,
        gender = gender,
        female = female,
        male = male,
        age_groups = age_groups,
        age_interval = age_interval,
        bin_width = bin_width,
        custom_breaks = custom_breaks,
        pct_base = pct_base,
        plot_values = plot_values,
        plot_title = plot_title,
        color_palette = color_palette,
        female_color = female_color,
        male_color = male_color,
        originaltheme = originaltheme,
        enableGGCharts = enableGGCharts,
        ggcharts_sort = ggcharts_sort,
        ggcharts_colors = ggcharts_colors,
        ggcharts_color1 = ggcharts_color1,
        ggcharts_color2 = ggcharts_color2,
        ggcharts_title = ggcharts_title,
        ggcharts_xlab = ggcharts_xlab)

    analysis <- agepyramidClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

